<script lang="ts">
	// The art is read from static/ rather than copied into src/: the file stays fetchable
	// at /ASCII.txt and `?raw` inlines that same byte-for-byte copy at build time, so
	// there is only ever one version of it to maintain.
	import source from '../../../static/ASCII.txt?raw';

	/**
	 * A decorative band of tiled ASCII art, opened in a window of its own ("ASCII.txt").
	 *
	 * The tile is *not* seamless: the pattern's lattice is generated by (+3 rows, -16
	 * cols) and (+8 rows, +23 cols), which puts its true horizontal period at 197
	 * columns while the file holds 70. Butting copies together therefore leaves faint
	 * misalignments at every edge, so the band is deliberately over-sized, bled past
	 * both viewport edges, and faded top and bottom — at that weight the seams read as
	 * part of the texture instead of as a broken repeat.
	 *
	 * `cols` is sized for the widest plausible display: 9 × 70 characters covers ~3800px
	 * at the band's font size. `rows` is how many times the tile stacks; the band's CSS
	 * height always clips it, so this only has to be generous.
	 */
	let { cols = 9, rows = 2 }: { cols?: number; rows?: number } = $props();

	const lines = source.replace(/\r/g, '').split('\n');
	const isCredit = (line: string) => /^by\s+\S/i.test(line.trim());

	// The file signs itself on its last line. That is a credit, not part of the pattern,
	// so it comes out of the tile and goes back in as readable text below the band.
	const pattern = lines.filter((line) => line.trim() !== '' && !isCredit(line));
	const artist = lines.find(isCredit)?.trim().replace(/^by\s+/i, '');

	// Trailing whitespace is stripped in the source, so every row has to be padded back
	// out to the tile width before it can repeat.
	const width = Math.max(...pattern.map((line) => line.length));

	const tile = $derived(pattern.map((line) => line.padEnd(width).repeat(cols)).join('\n'));
	const wall = $derived(Array.from({ length: rows }, () => tile).join('\n'));
</script>

<div class="win wall-win">
	<div class="win__bar">
		<span class="win__close" aria-hidden="true"></span>
		<p class="win__title">ASCII.txt</p>
		<span class="win__zoom" aria-hidden="true"></span>
	</div>

	<div class="wall" aria-hidden="true">
		<pre class="wall__tile">{wall}</pre>
	</div>

	{#if artist}
		<div class="win__status">
			<span>ASCII art by <a href="https://www.asciiart.eu/ascii-patterns/gallery" target="_blank" rel="noopener noreferrer">{artist}</a></span>
		</div>
	{/if}
</div>

<style>
	.wall {
		position: relative;
		overflow: hidden;
		height: clamp(10rem, 28vw, 18rem);
		pointer-events: none;
		background: var(--paper);
	}

	/* Centred on the viewport and wider than it, so the tiling bleeds off both edges
	   instead of ending on a visible column. */
	.wall__tile {
		position: absolute;
		top: 0;
		left: 50%;
		transform: translateX(-50%);
		width: max-content;
		margin: 0;
		font-family: var(--font-mono);
		font-size: 0.6875rem;
		line-height: 1.2;
		/* Texture, not meta text: lighter than --text-muted on purpose. */
		color: var(--text-muted);
		white-space: pre;
		user-select: none;
	}

	@media (max-width: 640px) {
		.wall__tile {
			font-size: 0.5625rem;
		}
	}
</style>
